d"]=[[npc200c]],["isVisible"]=1,["words"]=[[这西北之地有不少喜好毒物之人，赤练蛇在中原倒是常见，在这里便是难寻的东西了。]],["dsc"]=[[他身上背一个箩筐，手中拿着一把乌黑的长铁夹，腰间挂了一把短刀。手臂上有数个环形的旧疤，似乎是捕蛇时被咬伤所致。]]},{["skillPrepare"]={},["operations"]={{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[交谈]]}},["operationButton"]=[[交谈]],["faildResults"]={},["isVisible"]=1,["conditions"]={},["id"]=[[talk]]},{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[文本输出]],["arg2"]=[[我不接受你的物品。]]}},["operationButton"]=[[送礼]],["faildResults"]={{["arg1"]=[[文本输出]],["arg2"]=[[我不接受你的物品。]]}},["isVisible"]=1,["conditions"]={},["id"]=[[gift]]}},["name"]=[[小厮]],["baseId"]=[[fb50_200]],["skills"]={},["items"]={},["age"]=35,["sex"]=[[男]],["lv"]=10,["unitType"]=[[role]],["looks"]=16,["stageId"]=[[npc200d]],["isVisible"]=1,["words"]=[[在甘州这地界儿，恭王府就是半个皇城。]],["dsc"]=[[他是恭王府的小厮，自幼被遗弃，收养于王府中，平日负责打理花园的花草。]]},{["skillPrepare"]={},["operations"]={{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[交谈]]}},["operationButton"]=[[交谈]],["faildResults"]={},["isVisible"]=1,["conditions"]={},["id"]=[[talk]]},{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[文本输出]],["arg2"]=[[我不接受你的物品。]]}},["operationButton"]=[[送礼]],["faildResults"]={{["arg1"]=[[文本输出]],["arg2"]=[[我不接受你的物品。]]}},["isVisible"]=1,["conditions"]={},["id"]=[[gift]]}},["name"]=[[沐百元]],["baseId"]=[[fb50_200]],["skills"]={},["items"]={},["age"]=52,["sex"]=[[男]],["lv"]=10,["unitType"]=[[role]],["looks"]=20,["stageId"]=[[npc200e]],["isVisible"]=1,["words"]=[[自临烟离家后，这沐府便空荡了好多，也再没人同老夫下棋解趣，但愿她在外头别吃什么苦才好。;倩婧与我夫妻多年，临烟虽非她所出，但到底没有苛待，只是一直不准许临烟学她姨母一般练武罢了。]],["dsc"]=[[他是甘州通判，是沐临烟的父亲。本在朝为官，亲近萧王，萧王被恭王设计满门抄斩以后，被贬谪到甘州。]]},{["skillPrepare"]={{["lv"]=[[math.min(lv*0.75,1200)]],["preSkillType"]=0,["skillId"]=[[chunyanggong]]},{["lv"]=[[math.min(math.floor(lv*1.55+100),3000)]],["preSkillType"]=2,["skillId"]=[[jibenneigong]]},{["lv"]=[[math.min(math.floor(lv*1.55+100),3000)]],["preSkillType"]=3,["skillId"]=[[jibenqinggong]]},{["lv"]=[[math.min(math.floor(lv*1.55+100),3000